<?php require '../includes/functions.php';$u=require_role('citizen');verify_csrf();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=? AND id=?')->execute([$u['id'],(int)$_POST['id']]);redirect('citizen/notifications.php');}$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$u['id']]);$rows=$q->fetchAll();$pageTitle='Notifications';require '../includes/header.php';?><h1>Notifications</h1><?php foreach($rows as $n):?><section class="panel"><p><?=e($n['message'])?></p><small><?=e($n['created_at'])?> · <?=$n['read_at']?'Read':'Unread'?></small><?php if(!$n['read_at']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button>Mark as read</button></form><?php endif?></section><?php endforeach?><?php if(!$rows):?><p>No notifications yet.</p><?php endif?><?php require '../includes/footer.php';?>
